"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

PAGE_SIZE = 100

QUERY = """query Settlements($after: String) {
  settlements(first: 100, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}"""


class GraphQLError(RuntimeError):
    pass


def graphql(url, query, variables=None):
    body = json.dumps({"query": query, "variables": variables or {}}).encode()
    req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})
    while True:
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                result = json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code != 429:
                raise
            delay = exc.headers.get("Retry-After", "1")
            try:
                delay = float(delay)
            except ValueError:
                delay = 1.0
            time.sleep(delay)
            continue
        if result.get("errors"):
            raise GraphQLError(result["errors"])
        return result["data"]


def fetch_settlements(base_url):
    """Page through v2 settlements, keyed by id so re-delivered versions win."""
    url = f"{base_url.rstrip('/')}/v2/graphql"
    settlements = {}
    after = None
    restarts = 0
    while True:
        try:
            data = graphql(url, QUERY, {"after": after})
        except GraphQLError:
            # An expired/malformed cursor means we must start over without `after`.
            if after is not None and restarts < 3:
                restarts += 1
                after = None
                continue
            raise
        connection = data["settlements"]
        for settlement in connection["nodes"]:
            settlements[settlement["id"]] = settlement
        if not connection["pageInfo"]["hasNextPage"]:
            return list(settlements.values())
        after = connection["pageInfo"]["endCursor"]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()
    settlements = fetch_settlements(args.base_url)
    with open(args.out, "w") as f:
        for s in settlements:
            f.write(json.dumps(s) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

